pub unsafe fn xmlBufAdd(
    mut buf: xmlBufPtr,
    mut str: *const xmlChar,
    mut len: c_int,
) -> c_int {
    let mut needSize: size_t = 0;
    if str.is_null() || buf.is_null() || (*buf).error != 0 {
        return -(1 as c_int);
    }
    if (*buf).size != (*buf).compat_size as size_t {
        if (*buf).compat_size < INT_MAX as c_uint {
            (*buf).size = (*buf).compat_size as size_t;
        }
    }
    if (*buf).use_0 != (*buf).compat_use as size_t {
        if (*buf).compat_use < INT_MAX as c_uint {
            (*buf).use_0 = (*buf).compat_use as size_t;
        }
    }
    if len < -(1 as c_int) {
        return -(1 as c_int);
    }
    if len == 0 as c_int {
        return 0 as c_int;
    }
    if len < 0 as c_int {
        len = xmlStrlen(str);
    }
    if len < 0 as c_int {
        return -(1 as c_int);
    }
    if len == 0 as c_int {
        return 0 as c_int;
    }
    if len as size_t >= (*buf).size.wrapping_sub((*buf).use_0) {
        if len as size_t >= SIZE_MAX.wrapping_sub((*buf).use_0) {
            xmlBufMemoryError(
                buf,
                b"growing buffer past SIZE_MAX\0" as *const u8 as *const c_char,
            );
            return -(1 as c_int);
        }
        needSize = (*buf)
            .use_0
            .wrapping_add(len as size_t)
            .wrapping_add(1 as size_t);
        if (*buf).alloc as c_uint
            == XML_BUFFER_ALLOC_BOUNDED as c_int as c_uint
        {
            if needSize >= XML_MAX_TEXT_LENGTH as size_t {
                xmlBufMemoryError(
                    buf,
                    b"buffer error: text too long\n\0" as *const u8 as *const c_char,
                );
                return -(1 as c_int);
            }
        }
        if xmlBufResize(buf, needSize) == 0 {
            xmlBufMemoryError(
                buf,
                b"growing buffer\0" as *const u8 as *const c_char,
            );
            return XML_ERR_NO_MEMORY as c_int;
        }
    }
    memmove(
        (*buf).content.offset((*buf).use_0 as isize) as *mut xmlChar as *mut c_void,
        str as *const c_void,
        len as size_t,
    );
    (*buf).use_0 = ((*buf).use_0 as c_ulong).wrapping_add(len as c_ulong)
        as size_t as size_t;
    *(*buf).content.offset((*buf).use_0 as isize) = 0 as xmlChar;
    if (*buf).size < INT_MAX as size_t {
        (*buf).compat_size = (*buf).size as c_uint;
    } else {
        (*buf).compat_size = INT_MAX as c_uint;
    }
    if (*buf).use_0 < INT_MAX as size_t {
        (*buf).compat_use = (*buf).use_0 as c_uint;
    } else {
        (*buf).compat_use = INT_MAX as c_uint;
    }
    return 0 as c_int;
}
